const page = "<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n    <meta name=\"description\" content=\"A focused savings dashboard for a seven-day Vietnam trip.\" />\n    <title>Roam Fund — Vietnam trip savings</title>\n    <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\" />\n    <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin />\n    <link href=\"https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Manrope:wght@500;600;700;800&display=swap\" rel=\"stylesheet\" />\n    <link rel=\"stylesheet\" href=\"styles.css\" />\n  </head>\n  <body>\n    <div class=\"page-shell\">\n      <header class=\"topbar\">\n        <a class=\"brand\" href=\"#\" aria-label=\"Roam Fund home\">\n          <span class=\"brand-mark\" aria-hidden=\"true\">\n            <svg viewBox=\"0 0 32 32\"><path d=\"M8 22.5 23.6 7.8c.8-.7 2.1-.6 2.7.3.4.6.4 1.3 0 1.9L16 26.2l-3.5-7.8-6.9-4.6 2.4-2.3 7.2 2.1\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg>\n          </span>\n          <span>Roam Fund</span>\n        </a>\n        <div class=\"trip-switcher\">\n          <span class=\"flag\" aria-hidden=\"true\">🇻🇳</span>\n          <span>Vietnam</span>\n          <span class=\"soon-pill\">First trip</span>\n        </div>\n        <button class=\"icon-button\" id=\"resetButton\" type=\"button\" aria-label=\"Reset dashboard\" title=\"Reset dashboard\">\n          <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M20 11a8 8 0 1 0-2.34 5.66M20 4v7h-7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg>\n        </button>\n      </header>\n\n      <main>\n        <section class=\"hero\">\n          <div class=\"hero-copy\">\n            <p class=\"eyebrow\"><span></span> 7 days · Vietnam</p>\n            <h1>Your Vietnam fund,<br /><em>one step closer.</em></h1>\n            <p class=\"hero-subtitle\">A comfortable upper-range target for flights, beautiful stays and the experiences you’ll talk about for years.</p>\n          </div>\n          <div class=\"route-art\" aria-label=\"Vietnam route from Hanoi to Ho Chi Minh City\">\n            <svg viewBox=\"0 0 390 230\" role=\"img\" aria-hidden=\"true\">\n              <path class=\"route-line\" d=\"M95 45 C170 57, 122 118, 211 133 S257 202, 316 184\" />\n              <circle class=\"route-point point-a\" cx=\"95\" cy=\"45\" r=\"6\" />\n              <circle class=\"route-point point-b\" cx=\"211\" cy=\"133\" r=\"6\" />\n              <circle class=\"route-point point-c\" cx=\"316\" cy=\"184\" r=\"6\" />\n              <g class=\"plane\" transform=\"translate(177 105) rotate(25)\"><path d=\"M-15 4 17-5c4-1 6 1 3 4L5 8l-1 13-5 1-5-11-10 4-4-3 5-8Z\" /></g>\n              <text x=\"72\" y=\"25\">HANOI</text>\n              <text x=\"176\" y=\"158\">DA NANG</text>\n              <text x=\"279\" y=\"215\">HO CHI MINH</text>\n            </svg>\n          </div>\n        </section>\n\n        <section class=\"dashboard-grid\">\n          <article class=\"card progress-card\">\n            <div class=\"card-heading\">\n              <div>\n                <p class=\"label label-with-status\">SAVINGS PROGRESS <span class=\"live-pill\"><i></i> Shared live</span></p>\n                <h2 id=\"savedDisplay\">₹0</h2>\n                <p class=\"muted\">of <strong id=\"goalDisplay\">₹1,55,000</strong> target</p>\n              </div>\n              <div class=\"percent-badge\" id=\"percentDisplay\">0%</div>\n            </div>\n            <div class=\"progress-track\" role=\"progressbar\" aria-label=\"Trip savings progress\" aria-valuemin=\"0\" aria-valuemax=\"100\" aria-valuenow=\"0\">\n              <div class=\"progress-fill\" id=\"progressFill\"></div>\n              <div class=\"minimum-marker\" id=\"minimumMarker\" aria-hidden=\"true\"></div>\n            </div>\n            <div class=\"progress-meta\">\n              <span><b id=\"remainingDisplay\">₹1,55,000</b> to go</span>\n              <span id=\"paceDisplay\">Start your first deposit</span>\n            </div>\n            <div class=\"minimum-goal\" id=\"minimumGoal\">\n              <span class=\"minimum-goal-icon\" aria-hidden=\"true\">✓</span>\n              <span class=\"minimum-goal-copy\">\n                <strong>Minimum trip fund</strong>\n                <small id=\"minimumStatus\">Save ₹75,000 to be ready to go</small>\n              </span>\n              <strong class=\"minimum-goal-amount\" id=\"minimumDisplay\">₹75,000</strong>\n            </div>\n            <form class=\"deposit-form\" id=\"depositForm\">\n              <label for=\"amountInput\">Add to your fund</label>\n              <div class=\"amount-row\">\n                <div class=\"amount-input-wrap\">\n                  <span>₹</span>\n                  <input id=\"amountInput\" type=\"number\" inputmode=\"numeric\" min=\"1\" step=\"1\" placeholder=\"5,000\" required />\n                </div>\n                <button class=\"primary-button\" type=\"submit\">Add savings</button>\n              </div>\n              <div class=\"quick-amounts\" aria-label=\"Quick amounts\">\n                <button type=\"button\" data-amount=\"1000\">+ ₹1,000</button>\n                <button type=\"button\" data-amount=\"2500\">+ ₹2,500</button>\n                <button type=\"button\" data-amount=\"5000\">+ ₹5,000</button>\n                <button type=\"button\" data-amount=\"10000\">+ ₹10,000</button>\n              </div>\n            </form>\n          </article>\n\n          <aside class=\"card plan-card\">\n            <div class=\"plan-top\">\n              <div>\n                <p class=\"label\">TRIP PLAN</p>\n                <h3>Upper-comfort</h3>\n              </div>\n              <span class=\"researched-pill\">2026 researched</span>\n            </div>\n            <div class=\"setting-row\">\n              <div>\n                <span class=\"setting-label\">Travellers</span>\n                <span class=\"setting-note\">Target scales per person</span>\n              </div>\n              <div class=\"stepper\" aria-label=\"Number of travellers\">\n                <button id=\"decreaseTravellers\" type=\"button\" aria-label=\"Decrease travellers\">−</button>\n                <strong id=\"travellerCount\">1</strong>\n                <button id=\"increaseTravellers\" type=\"button\" aria-label=\"Increase travellers\">+</button>\n              </div>\n            </div>\n            <div class=\"setting-row date-row\">\n              <div>\n                <label class=\"setting-label\" for=\"tripDate\">Trip month</label>\n                <span class=\"setting-note\">Used for savings pace</span>\n              </div>\n              <input type=\"month\" id=\"tripDate\" />\n            </div>\n            <div class=\"goal-totals\">\n              <div>\n                <span>Minimum per person</span>\n                <strong>₹75,000</strong>\n              </div>\n              <div>\n                <span>Comfort target per person</span>\n                <strong>₹1,55,000</strong>\n              </div>\n            </div>\n          </aside>\n        </section>\n\n        <section class=\"budget-section\">\n          <div class=\"section-heading\">\n            <div>\n              <p class=\"label\">THE TARGET</p>\n              <h2>Where your money goes</h2>\n            </div>\n            <p>Upper-range estimates per person for 7 days, departing from an Indian metro.</p>\n          </div>\n\n          <div class=\"budget-grid\">\n            <article class=\"budget-card coral\">\n              <div class=\"budget-icon\"><svg viewBox=\"0 0 24 24\"><path d=\"m3 11 18-7-7 18-3-7-8-4Z\"/><path d=\"m11 15 4-4\"/></svg></div>\n              <span>Return flights</span>\n              <strong>₹40,000</strong>\n              <small>India ↔ Vietnam</small>\n            </article>\n            <article class=\"budget-card mint\">\n              <div class=\"budget-icon\"><svg viewBox=\"0 0 24 24\"><path d=\"M4 19V8h16v11M7 8V5h4v3M4 14h16M8 14v-3h4v3\"/></svg></div>\n              <span>Stay</span>\n              <strong>₹42,000</strong>\n              <small>6 nights · boutique / 4-star</small>\n            </article>\n            <article class=\"budget-card sky\">\n              <div class=\"budget-icon\"><svg viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"m15 9-2 4-4 2 2-4 4-2Z\"/></svg></div>\n              <span>Sightseeing</span>\n              <strong>₹28,000</strong>\n              <small>Cruise, tours & experiences</small>\n            </article>\n            <article class=\"budget-card yellow\">\n              <div class=\"budget-icon\"><svg viewBox=\"0 0 24 24\"><path d=\"M7 3v8M4 3v5a3 3 0 0 0 6 0V3M7 11v10M16 3c3 2 3 7 0 9v9M16 3v9\"/></svg></div>\n              <span>Food</span>\n              <strong>₹18,000</strong>\n              <small>Local favourites + special meals</small>\n            </article>\n            <article class=\"budget-card lavender\">\n              <div class=\"budget-icon\"><svg viewBox=\"0 0 24 24\"><path d=\"M5 16h14l-1-7H6l-1 7ZM7 16v3M17 16v3M8 12h8M8 6h8\"/></svg></div>\n              <span>Local travel</span>\n              <strong>₹12,000</strong>\n              <small>Transfers, Grab & domestic hop</small>\n            </article>\n            <article class=\"budget-card rose\">\n              <div class=\"budget-icon\"><svg viewBox=\"0 0 24 24\"><path d=\"M6 3h10a2 2 0 0 1 2 2v16H6a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2Z\"/><path d=\"M8 3v18M11 8h4M11 12h4M11 16h3\"/></svg></div>\n              <span>Visa & entry</span>\n              <strong>₹5,000</strong>\n              <small>e-Visa + payment cushion</small>\n            </article>\n            <article class=\"budget-card navy\">\n              <div class=\"budget-icon\"><svg viewBox=\"0 0 24 24\"><path d=\"M12 3v18M17 7.5C17 5.6 15 4 12 4S7 5.6 7 7.5s2 3 5 3 5 1.5 5 3.5-2 4-5 4-5-1.8-5-4\"/></svg></div>\n              <span>Comfort buffer</span>\n              <strong>₹10,000</strong>\n              <small>Price swings & surprises</small>\n            </article>\n          </div>\n        </section>\n\n        <section class=\"lower-grid\">\n          <article class=\"card activity-card\">\n            <div class=\"card-heading compact\">\n              <div>\n                <p class=\"label\">RECENT ACTIVITY</p>\n                <h3>Your contributions</h3>\n              </div>\n              <button class=\"text-button\" id=\"clearActivity\" type=\"button\">Clear mine</button>\n            </div>\n            <div class=\"empty-state\" id=\"emptyState\">\n              <span>₹</span>\n              <p>The shared fund starts here.</p>\n              <small>Add the first contribution for everyone to see.</small>\n            </div>\n            <ul class=\"activity-list\" id=\"activityList\" aria-live=\"polite\"></ul>\n          </article>\n\n          <article class=\"card research-card\">\n            <p class=\"label\">BUDGET NOTES</p>\n            <h3>Built with breathing room</h3>\n            <p>₹75,000 is the practical minimum fund for a lean seven-day trip with flights and visa covered. The ₹1,55,000 target adds room for better flight times, four-star stays and signature experiences.</p>\n            <div class=\"source-links\">\n              <a href=\"https://www.finnable.com/finn-advice/vietnam-trip-cost-from-india/\" target=\"_blank\" rel=\"noreferrer\">₹50k–₹1.8L trip range <span>↗</span></a>\n              <a href=\"https://www.tripsidekick.in/blog/vietnam-trip-cost-from-india\" target=\"_blank\" rel=\"noreferrer\">2026 flight benchmark <span>↗</span></a>\n              <a href=\"https://daytripsvietnam.com/guides/vietnam-hotel-prices-2026/\" target=\"_blank\" rel=\"noreferrer\">Hotel price ranges <span>↗</span></a>\n              <a href=\"https://evisa.xuatnhapcanh.gov.vn/en_US/web/guest/khai-thi-thuc-dien-tu/cap-thi-thuc-dien-tu\" target=\"_blank\" rel=\"noreferrer\">Official e-Visa fees <span>↗</span></a>\n            </div>\n            <small class=\"source-date\">Reviewed 22 Nov 2026 · Prices are planning estimates.</small>\n          </article>\n        </section>\n      </main>\n\n      <footer>\n        <span>Roam Fund</span>\n        <p>Make the plan. Build the fund. Take the trip.</p>\n      </footer>\n    </div>\n\n    <div class=\"toast\" id=\"toast\" role=\"status\" aria-live=\"polite\">Savings added</div>\n    <script src=\"app.js\"></script>\n  </body>\n</html>\n";
const styles = ":root {\n  --ink: #15251f;\n  --muted: #64716b;\n  --paper: #f5f6f1;\n  --card: #ffffff;\n  --green: #0b6b4c;\n  --green-dark: #07563d;\n  --green-soft: #dceee6;\n  --line: #dfe4dd;\n  --coral: #f1a18f;\n  --mint: #9ed8c3;\n  --sky: #9fc9df;\n  --yellow: #ebca73;\n  --lavender: #b9add8;\n  --navy: #4b6570;\n  --shadow: 0 18px 45px rgba(31, 54, 44, 0.08);\n}\n\n* { box-sizing: border-box; }\n\nhtml { scroll-behavior: smooth; }\n\nbody {\n  margin: 0;\n  min-width: 320px;\n  background: var(--paper);\n  color: var(--ink);\n  font-family: \"DM Sans\", sans-serif;\n  font-size: 16px;\n  -webkit-font-smoothing: antialiased;\n}\n\nbutton, input { font: inherit; }\nbutton { cursor: pointer; }\n\n.page-shell { min-height: 100vh; }\n\n.topbar {\n  height: 74px;\n  display: grid;\n  grid-template-columns: 1fr auto 1fr;\n  align-items: center;\n  max-width: 1240px;\n  margin: 0 auto;\n  padding: 0 28px;\n  border-bottom: 1px solid rgba(21, 37, 31, 0.1);\n}\n\n.brand {\n  display: inline-flex;\n  align-items: center;\n  gap: 10px;\n  width: fit-content;\n  color: var(--ink);\n  text-decoration: none;\n  font-family: \"Manrope\", sans-serif;\n  font-weight: 800;\n  letter-spacing: -0.03em;\n  font-size: 1.1rem;\n}\n\n.brand-mark {\n  display: grid;\n  place-items: center;\n  width: 34px;\n  height: 34px;\n  border-radius: 50%;\n  background: var(--green);\n  color: white;\n}\n\n.brand-mark svg { width: 21px; }\n\n.trip-switcher {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  padding: 8px 10px;\n  border-radius: 999px;\n  background: rgba(255,255,255,.7);\n  border: 1px solid var(--line);\n  font-size: .9rem;\n  font-weight: 700;\n}\n\n.flag { font-size: 1.15rem; }\n.soon-pill { padding: 3px 8px; border-radius: 999px; background: var(--green-soft); color: var(--green); font-size: .72rem; text-transform: uppercase; letter-spacing: .06em; }\n\n.icon-button {\n  justify-self: end;\n  display: grid;\n  place-items: center;\n  width: 40px;\n  height: 40px;\n  border: 1px solid var(--line);\n  border-radius: 50%;\n  background: transparent;\n  color: var(--muted);\n  transition: .2s ease;\n}\n.icon-button:hover { background: white; color: var(--green); transform: rotate(-20deg); }\n.icon-button svg { width: 20px; }\n\nmain { max-width: 1240px; margin: 0 auto; padding: 0 28px 80px; }\n\n.hero {\n  min-height: 360px;\n  display: grid;\n  grid-template-columns: 1.15fr .85fr;\n  align-items: center;\n  gap: 40px;\n  padding: 58px 0 42px;\n  overflow: hidden;\n}\n\n.eyebrow, .label { margin: 0; font-size: .78rem; font-weight: 800; letter-spacing: .12em; text-transform: uppercase; color: var(--green); }\n.label-with-status { display: flex; align-items: center; gap: 10px; }\n.live-pill { display: inline-flex; align-items: center; gap: 5px; padding: 4px 7px; border-radius: 999px; background: var(--green-soft); color: var(--green); font-size: .62rem; letter-spacing: .06em; }\n.live-pill i { width: 6px; height: 6px; border-radius: 50%; background: #26a36f; box-shadow: 0 0 0 3px rgba(38,163,111,.14); }\n.eyebrow { display: flex; align-items: center; gap: 9px; margin-bottom: 20px; }\n.eyebrow span { width: 22px; height: 2px; background: var(--coral); }\n\nh1, h2, h3 { font-family: \"Manrope\", sans-serif; margin: 0; letter-spacing: -.045em; }\nh1 { max-width: 690px; font-size: clamp(3rem, 5.9vw, 5rem); line-height: .98; font-weight: 800; }\nh1 em { color: var(--green); font-style: normal; }\n.hero-subtitle { max-width: 560px; margin: 24px 0 0; color: var(--muted); font-size: 1.04rem; line-height: 1.7; }\n\n.route-art { position: relative; align-self: stretch; display: grid; place-items: center; }\n.route-art::before { content: \"\"; position: absolute; width: 330px; height: 330px; border-radius: 50%; background: #e8eee7; }\n.route-art svg { position: relative; width: min(100%, 430px); overflow: visible; }\n.route-line { fill: none; stroke: #8ca69a; stroke-width: 2; stroke-dasharray: 6 7; }\n.route-point { fill: var(--paper); stroke: var(--green); stroke-width: 3; }\n.point-b { stroke: var(--coral); }\n.route-art text { fill: var(--ink); font: 700 11px \"DM Sans\", sans-serif; letter-spacing: .1em; }\n.plane { fill: var(--green); animation: float 3s ease-in-out infinite; transform-origin: center; }\n@keyframes float { 0%, 100% { translate: 0 0; } 50% { translate: 0 -5px; } }\n\n.dashboard-grid { display: grid; grid-template-columns: minmax(0, 1.6fr) minmax(300px, .7fr); gap: 22px; }\n.card { background: var(--card); border: 1px solid rgba(21,37,31,.07); border-radius: 22px; box-shadow: var(--shadow); }\n.progress-card { padding: 30px; }\n.card-heading { display: flex; align-items: flex-start; justify-content: space-between; gap: 20px; }\n.card-heading h2 { margin-top: 13px; font-size: clamp(2.5rem, 5vw, 4.2rem); line-height: 1; }\n.card-heading .muted { margin: 8px 0 0; color: var(--muted); }\n.percent-badge { padding: 9px 12px; border-radius: 10px; background: var(--green-soft); color: var(--green); font-family: \"Manrope\"; font-weight: 800; }\n.progress-track { position: relative; height: 12px; margin-top: 28px; overflow: hidden; border-radius: 999px; background: #e8ece8; }\n.progress-fill { width: 0%; height: 100%; border-radius: inherit; background: linear-gradient(90deg, var(--green), #28a473); transition: width .6s cubic-bezier(.2,.8,.2,1); }\n.minimum-marker { position: absolute; top: 0; bottom: 0; width: 3px; background: var(--ink); box-shadow: 0 0 0 1px rgba(255,255,255,.65); transform: translateX(-1px); }\n.progress-meta { display: flex; justify-content: space-between; gap: 16px; margin-top: 10px; color: var(--muted); font-size: .84rem; }\n.progress-meta b { color: var(--ink); }\n\n.minimum-goal { display: grid; grid-template-columns: 38px 1fr auto; align-items: center; gap: 11px; margin-top: 20px; padding: 13px 15px; border: 1px solid #d5dfd9; border-radius: 13px; background: #f4f8f5; }\n.minimum-goal-icon { display: grid; place-items: center; width: 38px; height: 38px; border-radius: 50%; background: #e1e7e3; color: #89958f; font-weight: 800; }\n.minimum-goal-copy strong, .minimum-goal-copy small { display: block; }\n.minimum-goal-copy strong { font-size: .85rem; }\n.minimum-goal-copy small { margin-top: 3px; color: var(--muted); font-size: .76rem; }\n.minimum-goal-amount { font-family: \"Manrope\"; color: var(--ink); }\n.minimum-goal.reached { border-color: #9bcab7; background: var(--green-soft); }\n.minimum-goal.reached .minimum-goal-icon { background: var(--green); color: white; }\n.minimum-goal.reached .minimum-goal-copy small { color: var(--green-dark); }\n\n.deposit-form { margin-top: 30px; padding-top: 25px; border-top: 1px solid var(--line); }\n.deposit-form > label { display: block; margin-bottom: 9px; font-weight: 700; }\n.amount-row { display: grid; grid-template-columns: minmax(0,1fr) auto; gap: 10px; }\n.amount-input-wrap { display: flex; align-items: center; gap: 8px; height: 52px; padding: 0 16px; border: 1.5px solid var(--line); border-radius: 12px; transition: .2s; }\n.amount-input-wrap:focus-within { border-color: var(--green); box-shadow: 0 0 0 3px rgba(11,107,76,.1); }\n.amount-input-wrap span { color: var(--green); font-weight: 800; }\n.amount-input-wrap input { width: 100%; border: 0; outline: 0; font-size: 1.1rem; background: transparent; color: var(--ink); }\n.primary-button { padding: 0 24px; border: 0; border-radius: 12px; background: var(--green); color: white; font-weight: 800; transition: .2s; }\n.primary-button:hover { background: var(--green-dark); transform: translateY(-1px); }\n.primary-button:disabled, .quick-amounts button:disabled { cursor: wait; opacity: .6; transform: none; }\n.quick-amounts { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 11px; }\n.quick-amounts button { padding: 7px 11px; border: 1px solid var(--line); border-radius: 8px; background: #fafbf9; color: var(--muted); font-size: .78rem; font-weight: 700; }\n.quick-amounts button:hover { border-color: var(--green); color: var(--green); }\n\n.plan-card { padding: 26px; background: var(--ink); color: white; box-shadow: none; }\n.plan-card .label { color: var(--mint); }\n.plan-top { display: flex; justify-content: space-between; align-items: flex-start; gap: 10px; padding-bottom: 22px; }\n.plan-top h3 { margin-top: 8px; font-size: 1.65rem; }\n.researched-pill { padding: 5px 8px; border: 1px solid rgba(255,255,255,.2); border-radius: 8px; color: #c8d4ce; font-size: .7rem; }\n.setting-row { display: flex; justify-content: space-between; align-items: center; gap: 16px; padding: 20px 0; border-top: 1px solid rgba(255,255,255,.12); }\n.setting-label { display: block; font-weight: 700; }\n.setting-note { display: block; margin-top: 4px; color: #9dadA6; font-size: .76rem; }\n.stepper { display: flex; align-items: center; overflow: hidden; border: 1px solid rgba(255,255,255,.2); border-radius: 10px; }\n.stepper button { width: 35px; height: 35px; border: 0; background: rgba(255,255,255,.05); color: white; font-size: 1.2rem; }\n.stepper button:hover { background: rgba(255,255,255,.14); }\n.stepper strong { width: 34px; text-align: center; }\n.date-row input { width: 135px; padding: 8px 9px; border: 1px solid rgba(255,255,255,.2); border-radius: 9px; background: rgba(255,255,255,.06); color: white; color-scheme: dark; font-size: .78rem; }\n.goal-totals { padding-top: 8px; border-top: 1px solid rgba(255,255,255,.12); }\n.goal-totals > div { display: flex; justify-content: space-between; align-items: baseline; gap: 14px; padding-top: 11px; color: #b8c4be; font-size: .78rem; }\n.goal-totals strong { color: white; font-family: \"Manrope\"; font-size: 1.08rem; }\n.goal-totals > div:last-child strong { color: var(--mint); }\n\n.budget-section { margin-top: 76px; }\n.section-heading { display: flex; justify-content: space-between; align-items: end; gap: 30px; margin-bottom: 24px; }\n.section-heading h2 { margin-top: 8px; font-size: clamp(2rem,4vw,3rem); }\n.section-heading > p { max-width: 440px; margin: 0 0 5px; color: var(--muted); line-height: 1.6; text-align: right; }\n.budget-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 12px; }\n.budget-card { min-height: 210px; padding: 20px; display: flex; flex-direction: column; border-radius: 18px; color: #16241f; transition: .2s ease; }\n.budget-card:hover { transform: translateY(-4px); box-shadow: 0 13px 28px rgba(31,54,44,.10); }\n.budget-card.coral { background: #f7d1c8; }\n.budget-card.mint { background: #d2eee4; }\n.budget-card.sky { background: #d8ebf3; }\n.budget-card.yellow { background: #f4e3b5; }\n.budget-card.lavender { background: #e5def3; }\n.budget-card.rose { background: #f1d8df; }\n.budget-card.navy { background: #38505a; color: white; }\n.budget-icon { display: grid; place-items: center; width: 42px; height: 42px; margin-bottom: auto; border-radius: 12px; background: rgba(255,255,255,.48); }\n.navy .budget-icon { background: rgba(255,255,255,.13); }\n.budget-icon svg { width: 23px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }\n.budget-card span { margin-top: 18px; color: currentColor; font-size: .8rem; font-weight: 700; opacity: .75; }\n.budget-card strong { margin-top: 3px; font-family: \"Manrope\"; font-size: 1.45rem; letter-spacing: -.04em; }\n.budget-card small { margin-top: 5px; font-size: .7rem; line-height: 1.35; opacity: .65; }\n\n.lower-grid { display: grid; grid-template-columns: 1.2fr .8fr; gap: 22px; margin-top: 22px; }\n.activity-card, .research-card { padding: 26px; }\n.compact { align-items: center; }\n.compact h3, .research-card h3 { margin-top: 7px; font-size: 1.4rem; }\n.text-button { border: 0; background: transparent; color: var(--muted); font-size: .8rem; text-decoration: underline; text-underline-offset: 3px; }\n.empty-state { display: grid; justify-items: center; padding: 35px 20px 23px; color: var(--muted); text-align: center; }\n.empty-state span { display: grid; place-items: center; width: 43px; height: 43px; border-radius: 50%; background: var(--green-soft); color: var(--green); font-weight: 800; }\n.empty-state p { margin: 12px 0 3px; color: var(--ink); font-weight: 700; }\n.empty-state small { font-size: .8rem; }\n.activity-list { list-style: none; margin: 20px 0 0; padding: 0; }\n.activity-list li { display: grid; grid-template-columns: 36px 1fr auto auto; align-items: center; gap: 12px; padding: 12px 0; border-top: 1px solid var(--line); }\n.activity-dot { display: grid; place-items: center; width: 36px; height: 36px; border-radius: 50%; background: var(--green-soft); color: var(--green); font-weight: 800; }\n.activity-copy strong, .activity-copy small { display: block; }\n.activity-copy small { margin-top: 2px; color: var(--muted); font-size: .74rem; }\n.activity-amount { color: var(--green); font-family: \"Manrope\"; font-weight: 800; }\n.delete-entry { width: 29px; height: 29px; border: 0; border-radius: 50%; background: transparent; color: #96a19c; font-size: 1.2rem; }\n.delete-entry:hover { background: #f4e5e2; color: #a14d3e; }\n.shared-entry { padding: 4px 7px; border-radius: 999px; background: #eef2ef; color: var(--muted); font-size: .68rem; font-weight: 700; }\n\n.research-card { background: #e5eee8; box-shadow: none; }\n.research-card > p:not(.label) { margin: 15px 0 20px; color: #4d5e56; line-height: 1.6; }\n.source-links { display: grid; gap: 8px; }\n.source-links a { display: flex; justify-content: space-between; padding: 10px 12px; border-radius: 9px; background: rgba(255,255,255,.6); color: var(--green-dark); font-size: .81rem; font-weight: 700; text-decoration: none; }\n.source-links a:hover { background: white; }\n.source-date { display: block; margin-top: 16px; color: #718078; font-size: .7rem; }\n\nfooter { max-width: 1184px; margin: 0 auto; padding: 26px 0 40px; border-top: 1px solid rgba(21,37,31,.1); display: flex; justify-content: space-between; color: var(--muted); font-size: .8rem; }\nfooter span { color: var(--ink); font-family: \"Manrope\"; font-weight: 800; }\nfooter p { margin: 0; }\n\n.toast { position: fixed; left: 50%; bottom: 24px; transform: translate(-50%, 30px); padding: 11px 18px; border-radius: 999px; background: var(--ink); color: white; box-shadow: var(--shadow); font-size: .85rem; font-weight: 700; opacity: 0; pointer-events: none; transition: .25s; }\n.toast.show { opacity: 1; transform: translate(-50%, 0); }\n\n@media (max-width: 1050px) {\n  .budget-grid { grid-template-columns: repeat(3, 1fr); }\n  .budget-card { min-height: 195px; }\n}\n\n@media (max-width: 780px) {\n  .topbar { grid-template-columns: 1fr auto; padding: 0 18px; }\n  .trip-switcher { display: none; }\n  main { padding: 0 18px 60px; }\n  .hero { grid-template-columns: 1fr; min-height: auto; padding-top: 50px; }\n  .route-art { display: none; }\n  .dashboard-grid, .lower-grid { grid-template-columns: 1fr; }\n  .section-heading { align-items: flex-start; flex-direction: column; gap: 12px; }\n  .section-heading > p { text-align: left; }\n  footer { margin: 0 18px; }\n}\n\n@media (max-width: 560px) {\n  h1 { font-size: 2.8rem; }\n  .hero { padding: 42px 0 34px; }\n  .progress-card { padding: 22px; }\n  .card-heading h2 { font-size: 2.7rem; }\n  .amount-row { grid-template-columns: 1fr; }\n  .primary-button { height: 50px; }\n  .progress-meta { flex-direction: column; gap: 4px; }\n  .minimum-goal { grid-template-columns: 36px 1fr; }\n  .minimum-goal-amount { grid-column: 2; margin-top: -5px; }\n  .budget-grid { grid-template-columns: repeat(2, 1fr); }\n  .budget-card { min-height: 182px; padding: 16px; }\n  .budget-section { margin-top: 56px; }\n  footer { flex-direction: column; gap: 7px; }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  *, *::before, *::after { scroll-behavior: auto !important; animation: none !important; transition: none !important; }\n}\n";
const app = "const PER_PERSON_TARGET = 155000;\nconst PER_PERSON_MINIMUM = 75000;\nconst STORAGE_KEY = \"roam-fund-vietnam-v2\";\nconst CLIENT_KEY = \"roam-fund-client-id\";\nconst MIGRATION_KEY = \"roam-fund-shared-migration-v1\";\n\nconst defaultState = {\n  travellers: 1,\n  tripDate: \"2027-11\",\n  contributions: [],\n  totalSaved: 0,\n  loading: true\n};\n\nlet legacyContributions = [];\nlet state = loadState();\nconst clientId = getClientId();\n\nconst els = {\n  depositForm: document.querySelector(\"#depositForm\"),\n  amountInput: document.querySelector(\"#amountInput\"),\n  savedDisplay: document.querySelector(\"#savedDisplay\"),\n  goalDisplay: document.querySelector(\"#goalDisplay\"),\n  remainingDisplay: document.querySelector(\"#remainingDisplay\"),\n  percentDisplay: document.querySelector(\"#percentDisplay\"),\n  progressFill: document.querySelector(\"#progressFill\"),\n  progressTrack: document.querySelector(\".progress-track\"),\n  minimumMarker: document.querySelector(\"#minimumMarker\"),\n  minimumGoal: document.querySelector(\"#minimumGoal\"),\n  minimumDisplay: document.querySelector(\"#minimumDisplay\"),\n  minimumStatus: document.querySelector(\"#minimumStatus\"),\n  paceDisplay: document.querySelector(\"#paceDisplay\"),\n  travellerCount: document.querySelector(\"#travellerCount\"),\n  tripDate: document.querySelector(\"#tripDate\"),\n  activityList: document.querySelector(\"#activityList\"),\n  emptyState: document.querySelector(\"#emptyState\"),\n  clearActivity: document.querySelector(\"#clearActivity\"),\n  toast: document.querySelector(\"#toast\")\n};\n\nfunction loadState() {\n  try {\n    const stored = JSON.parse(localStorage.getItem(STORAGE_KEY));\n    legacyContributions = Array.isArray(stored?.contributions) ? stored.contributions : [];\n    return {\n      ...structuredClone(defaultState),\n      travellers: Number(stored?.travellers) || defaultState.travellers,\n      tripDate: stored?.tripDate || defaultState.tripDate\n    };\n  } catch {\n    return structuredClone(defaultState);\n  }\n}\n\nfunction getClientId() {\n  const stored = localStorage.getItem(CLIENT_KEY);\n  if (stored) return stored;\n  const id = crypto.randomUUID();\n  localStorage.setItem(CLIENT_KEY, id);\n  return id;\n}\n\nfunction savePreferences() {\n  localStorage.setItem(STORAGE_KEY, JSON.stringify({\n    travellers: state.travellers,\n    tripDate: state.tripDate\n  }));\n}\n\nfunction formatCurrency(value) {\n  return new Intl.NumberFormat(\"en-IN\", {\n    style: \"currency\",\n    currency: \"INR\",\n    maximumFractionDigits: 0\n  }).format(value);\n}\n\nfunction getMonthsRemaining() {\n  if (!state.tripDate) return 0;\n  const [year, month] = state.tripDate.split(\"-\").map(Number);\n  const now = new Date();\n  return Math.max(1, (year - now.getFullYear()) * 12 + month - now.getMonth());\n}\n\nfunction render() {\n  const target = PER_PERSON_TARGET * state.travellers;\n  const minimum = PER_PERSON_MINIMUM * state.travellers;\n  const saved = state.totalSaved;\n  const remaining = Math.max(0, target - saved);\n  const minimumRemaining = Math.max(0, minimum - saved);\n  const percent = Math.min(100, Math.round((saved / target) * 100));\n  const months = getMonthsRemaining();\n\n  els.savedDisplay.textContent = state.loading ? \"—\" : formatCurrency(saved);\n  els.goalDisplay.textContent = formatCurrency(target);\n  els.remainingDisplay.textContent = formatCurrency(remaining);\n  els.percentDisplay.textContent = `${percent}%`;\n  els.progressFill.style.width = `${percent}%`;\n  els.progressTrack.setAttribute(\"aria-valuenow\", percent);\n  els.progressTrack.setAttribute(\"aria-valuetext\", `${formatCurrency(saved)} saved; minimum ${formatCurrency(minimum)}; comfort target ${formatCurrency(target)}`);\n  els.minimumMarker.style.left = `${(minimum / target) * 100}%`;\n  els.minimumDisplay.textContent = formatCurrency(minimum);\n  els.minimumGoal.classList.toggle(\"reached\", minimumRemaining === 0 && !state.loading);\n  els.minimumStatus.textContent = state.loading\n    ? \"Loading the shared fund…\"\n    : minimumRemaining === 0\n      ? \"Minimum reached — you’re ready to go!\"\n      : `${formatCurrency(minimumRemaining)} left to be ready to go`;\n  els.travellerCount.textContent = state.travellers;\n  els.tripDate.value = state.tripDate;\n\n  if (state.loading) {\n    els.paceDisplay.textContent = \"Syncing shared savings…\";\n  } else if (!saved) {\n    els.paceDisplay.textContent = \"Start the shared fund\";\n  } else if (!remaining) {\n    els.paceDisplay.textContent = \"Target reached — Vietnam awaits!\";\n  } else if (months) {\n    els.paceDisplay.textContent = `${formatCurrency(Math.ceil(remaining / months))}/month to goal`;\n  }\n\n  renderActivity();\n}\n\nfunction renderActivity() {\n  els.activityList.innerHTML = \"\";\n  els.emptyState.hidden = state.loading || state.contributions.length > 0;\n  els.clearActivity.hidden = !state.contributions.some((item) => item.isOwn);\n\n  state.contributions.slice(0, 8).forEach((item) => {\n    const li = document.createElement(\"li\");\n    const date = new Intl.DateTimeFormat(\"en-IN\", { day: \"numeric\", month: \"short\", year: \"numeric\" }).format(new Date(item.date));\n    const action = item.isOwn\n      ? `<button class=\"delete-entry\" type=\"button\" aria-label=\"Delete ${formatCurrency(item.amount)} contribution\" data-id=\"${item.id}\">×</button>`\n      : `<span class=\"shared-entry\">Shared</span>`;\n    li.innerHTML = `\n      <span class=\"activity-dot\">+</span>\n      <span class=\"activity-copy\"><strong>${item.isOwn ? \"Your contribution\" : \"Fund contribution\"}</strong><small>${date}</small></span>\n      <span class=\"activity-amount\">+${formatCurrency(item.amount)}</span>\n      ${action}\n    `;\n    els.activityList.appendChild(li);\n  });\n}\n\nasync function requestSavings(path = \"\", options = {}) {\n  const response = await fetch(`/api/savings${path}`, {\n    ...options,\n    headers: { \"content-type\": \"application/json\", ...(options.headers || {}) }\n  });\n  const data = response.status === 204 ? {} : await response.json().catch(() => ({}));\n  if (!response.ok) throw new Error(data.error || \"The shared fund could not be updated\");\n  return data;\n}\n\nasync function fetchSavings({ quiet = false } = {}) {\n  try {\n    const data = await requestSavings(`?clientId=${encodeURIComponent(clientId)}`);\n    state.contributions = data.contributions;\n    state.totalSaved = data.total;\n    state.loading = false;\n    render();\n  } catch (error) {\n    state.loading = false;\n    render();\n    if (!quiet) showToast(error.message || \"Could not load shared savings\");\n  }\n}\n\nasync function migrateLegacySavings() {\n  if (!legacyContributions.length || localStorage.getItem(MIGRATION_KEY)) return;\n  for (const item of legacyContributions) {\n    await requestSavings(\"\", {\n      method: \"POST\",\n      body: JSON.stringify({ amount: item.amount, clientId })\n    });\n  }\n  localStorage.setItem(MIGRATION_KEY, \"done\");\n  legacyContributions = [];\n  savePreferences();\n}\n\nasync function addContribution(amount) {\n  if (!Number.isFinite(amount) || amount <= 0) return;\n  setSaving(true);\n  try {\n    const data = await requestSavings(\"\", {\n      method: \"POST\",\n      body: JSON.stringify({ amount: Math.round(amount), clientId })\n    });\n    state.contributions.unshift(data.contribution);\n    state.totalSaved = data.total;\n    render();\n    showToast(`${formatCurrency(amount)} added to the shared fund`);\n  } catch (error) {\n    showToast(error.message || \"Savings could not be added\");\n  } finally {\n    setSaving(false);\n  }\n}\n\nfunction setSaving(isSaving) {\n  els.amountInput.disabled = isSaving;\n  els.depositForm.querySelector(\".primary-button\").disabled = isSaving;\n  document.querySelectorAll(\"[data-amount]\").forEach((button) => { button.disabled = isSaving; });\n}\n\nlet toastTimer;\nfunction showToast(message) {\n  els.toast.textContent = message;\n  els.toast.classList.add(\"show\");\n  clearTimeout(toastTimer);\n  toastTimer = setTimeout(() => els.toast.classList.remove(\"show\"), 2800);\n}\n\nels.depositForm.addEventListener(\"submit\", async (event) => {\n  event.preventDefault();\n  await addContribution(Number(els.amountInput.value));\n  els.amountInput.value = \"\";\n  els.amountInput.focus();\n});\n\ndocument.querySelectorAll(\"[data-amount]\").forEach((button) => {\n  button.addEventListener(\"click\", () => addContribution(Number(button.dataset.amount)));\n});\n\ndocument.querySelector(\"#decreaseTravellers\").addEventListener(\"click\", () => {\n  state.travellers = Math.max(1, state.travellers - 1);\n  savePreferences();\n  render();\n});\n\ndocument.querySelector(\"#increaseTravellers\").addEventListener(\"click\", () => {\n  state.travellers = Math.min(12, state.travellers + 1);\n  savePreferences();\n  render();\n});\n\nels.tripDate.addEventListener(\"change\", () => {\n  state.tripDate = els.tripDate.value;\n  savePreferences();\n  render();\n});\n\nels.activityList.addEventListener(\"click\", async (event) => {\n  const button = event.target.closest(\"[data-id]\");\n  if (!button) return;\n  button.disabled = true;\n  try {\n    const data = await requestSavings(`/${encodeURIComponent(button.dataset.id)}`, {\n      method: \"DELETE\",\n      body: JSON.stringify({ clientId })\n    });\n    state.contributions = state.contributions.filter((item) => item.id !== button.dataset.id);\n    state.totalSaved = data.total;\n    render();\n    showToast(\"Contribution removed from the shared fund\");\n  } catch (error) {\n    button.disabled = false;\n    showToast(error.message || \"Contribution could not be removed\");\n  }\n});\n\nels.clearActivity.addEventListener(\"click\", async () => {\n  try {\n    const data = await requestSavings(\"\", {\n      method: \"DELETE\",\n      body: JSON.stringify({ clientId })\n    });\n    state.contributions = state.contributions.filter((item) => !item.isOwn);\n    state.totalSaved = data.total;\n    render();\n    showToast(\"Your contributions were cleared\");\n  } catch (error) {\n    showToast(error.message || \"Contributions could not be cleared\");\n  }\n});\n\ndocument.querySelector(\"#resetButton\").addEventListener(\"click\", () => {\n  if (!window.confirm(\"Reset traveller count and trip month? Shared savings will stay intact.\")) return;\n  state.travellers = defaultState.travellers;\n  state.tripDate = defaultState.tripDate;\n  savePreferences();\n  render();\n  showToast(\"Trip settings reset\");\n});\n\nasync function start() {\n  render();\n  try {\n    await migrateLegacySavings();\n  } catch {\n    showToast(\"Your previous browser savings could not be migrated yet\");\n  }\n  await fetchSavings();\n  window.setInterval(() => fetchSavings({ quiet: true }), 15000);\n}\n\ndocument.addEventListener(\"visibilitychange\", () => {\n  if (document.visibilityState === \"visible\") fetchSavings({ quiet: true });\n});\n\nstart();\n";

const jsonHeaders = {
  "content-type": "application/json; charset=utf-8",
  "cache-control": "no-store"
};

function json(data, status = 200) {
  return new Response(JSON.stringify(data), { status, headers: jsonHeaders });
}

function validClientId(value) {
  return typeof value === "string" && /^[0-9a-f-]{36}$/i.test(value);
}

function isoDate(value) {
  if (!value) return new Date().toISOString();
  const normalized = String(value).replace(" ", "T");
  return normalized.endsWith("Z") ? normalized : `${normalized}Z`;
}

async function readPayload(request) {
  try {
    return await request.json();
  } catch {
    return {};
  }
}

async function getFund(request, env) {
  const clientId = new URL(request.url).searchParams.get("clientId") || "";
  const [recentResult, totalResult] = await env.DB.batch([
    env.DB.prepare("SELECT id, owner_id, amount, created_at FROM contributions ORDER BY created_at DESC, id DESC LIMIT 50"),
    env.DB.prepare("SELECT COALESCE(SUM(amount), 0) AS total FROM contributions")
  ]);
  const contributions = (recentResult.results || []).map((row) => ({
    id: row.id,
    amount: Number(row.amount),
    date: isoDate(row.created_at),
    isOwn: validClientId(clientId) && row.owner_id === clientId
  }));
  return json({ contributions, total: Number(totalResult.results?.[0]?.total || 0) });
}

async function addToFund(request, env) {
  const payload = await readPayload(request);
  const amount = Math.round(Number(payload.amount));
  const clientId = payload.clientId;
  if (!validClientId(clientId)) return json({ error: "A valid browser ID is required" }, 400);
  if (!Number.isFinite(amount) || amount < 1 || amount > 1000000) {
    return json({ error: "Enter an amount between ₹1 and ₹10,00,000" }, 400);
  }

  const id = crypto.randomUUID();
  const createdAt = new Date().toISOString();
  const [insertResult, totalResult] = await env.DB.batch([
    env.DB.prepare("INSERT INTO contributions (id, owner_id, amount, created_at) SELECT ?, ?, ?, ? WHERE (SELECT COUNT(*) FROM contributions WHERE owner_id = ?) < 500")
      .bind(id, clientId, amount, createdAt, clientId),
    env.DB.prepare("SELECT COALESCE(SUM(amount), 0) AS total FROM contributions")
  ]);
  if (!insertResult.meta?.changes) return json({ error: "This browser has reached its contribution limit" }, 429);
  return json({
    contribution: { id, amount, date: createdAt, isOwn: true },
    total: Number(totalResult.results?.[0]?.total || 0)
  }, 201);
}

async function removeFromFund(request, env, id) {
  const payload = await readPayload(request);
  const clientId = payload.clientId;
  if (!validClientId(clientId)) return json({ error: "A valid browser ID is required" }, 400);
  const [deleteResult, totalResult] = await env.DB.batch([
    env.DB.prepare("DELETE FROM contributions WHERE id = ? AND owner_id = ?").bind(id, clientId),
    env.DB.prepare("SELECT COALESCE(SUM(amount), 0) AS total FROM contributions")
  ]);
  if (!deleteResult.meta?.changes) return json({ error: "Only your own contributions can be removed" }, 404);
  return json({ total: Number(totalResult.results?.[0]?.total || 0) });
}

async function clearOwnFund(request, env) {
  const payload = await readPayload(request);
  const clientId = payload.clientId;
  if (!validClientId(clientId)) return json({ error: "A valid browser ID is required" }, 400);
  const [, totalResult] = await env.DB.batch([
    env.DB.prepare("DELETE FROM contributions WHERE owner_id = ?").bind(clientId),
    env.DB.prepare("SELECT COALESCE(SUM(amount), 0) AS total FROM contributions")
  ]);
  return json({ total: Number(totalResult.results?.[0]?.total || 0) });
}

async function handleApi(request, env, path) {
  if (!env.DB) return json({ error: "Shared savings database is unavailable" }, 503);
  if (path === "/api/savings" && request.method === "GET") return getFund(request, env);
  if (path === "/api/savings" && request.method === "POST") return addToFund(request, env);
  if (path === "/api/savings" && request.method === "DELETE") return clearOwnFund(request, env);
  if (path.startsWith("/api/savings/") && request.method === "DELETE") {
    return removeFromFund(request, env, decodeURIComponent(path.slice("/api/savings/".length)));
  }
  return json({ error: "Not found" }, 404);
}

export default {
  async fetch(request, env) {
    const path = new URL(request.url).pathname;
    try {
      if (path.startsWith("/api/")) return await handleApi(request, env, path);
      if (request.method !== "GET" && request.method !== "HEAD") return new Response("Method not allowed", { status: 405 });
      if (path === "/" || path === "/index.html") return new Response(page, { headers: { "content-type": "text/html; charset=utf-8", "cache-control": "no-cache" } });
      if (path === "/styles.css") return new Response(styles, { headers: { "content-type": "text/css; charset=utf-8", "cache-control": "no-cache" } });
      if (path === "/app.js") return new Response(app, { headers: { "content-type": "text/javascript; charset=utf-8", "cache-control": "no-cache" } });
      return new Response("Not found", { status: 404 });
    } catch (error) {
      console.error("Worker request failed", error);
      return path.startsWith("/api/")
        ? json({ error: "The shared fund is temporarily unavailable" }, 500)
        : new Response("The site is temporarily unavailable", { status: 500 });
    }
  }
};
